export interface WordData {
  word: string
  /** First hint: a gentle nudge toward the word that does not give it away */
  clue: string
  fact: string
  /** One https URL for the best source supporting the fact */
  source: string
  category: Category
}

export const CATEGORIES = ['Energy', 'Health', 'Nature', 'Peace', 'Rights', 'Tech'] as const
export type Category = (typeof CATEGORIES)[number]

export const MIN_WORD_LENGTH = 5
export const MAX_WORD_LENGTH = 12

const entry = (word: string, category: Category, clue: string, fact: string, source: string): WordData => ({
  word,
  clue,
  fact,
  source,
  category,
})

